pageCss:
.oct-table{border-collapse:collapse;width:100%;margin:0 0 14px;font-size:9.5pt}
.oct-table th{text-align:left;background:#eaf0f9;border:1px solid #c3ced0;padding:4px 7px;font-family:var(--font-caption)}
.oct-table td{border:1px solid #d8dfeb;padding:4px 7px;vertical-align:top}
.oct-table td:not(:first-child){text-align:right;font-family:var(--font-mono)}
.oct-table tr.mine td{background:#fffbe8}
.oct-demo{border:1px solid #99a8bd;background:#f3f6fa;box-shadow:inset 1px 1px 0 #fff;margin:0 0 14px}
.oct-demo-head{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;background:linear-gradient(180deg,#eaf0f9,#dbe4f1);border-bottom:1px solid #b6c2d4;padding:5px 9px;font-family:var(--font-caption);font-weight:bold;font-size:9.5pt;color:#20406e}
.oct-reveal{font:inherit;font-size:8.5pt;font-weight:normal;font-family:var(--font-ui);padding:3px 11px;cursor:pointer;background:linear-gradient(180deg,#fff,#e4e9f2);border:1px solid #8c9ab0;border-radius:3px;color:#243}
.oct-reveal:disabled{color:#8b96a6;cursor:default}
.oct-bars{list-style:none;margin:0;padding:10px 12px 4px}
.oct-bars li{display:grid;grid-template-columns:11em 1fr auto;align-items:center;gap:8px;margin:0 0 7px;font-size:9pt}
.oct-bars .n{font-family:var(--font-mono);color:#33455f;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.oct-bars .t{height:15px;background:linear-gradient(180deg,#7fb0e8,#3f7fd0);border:1px solid #2f5f9e;min-width:2px;transition:width .32s ease}
.oct-bars li.mine .t{background:linear-gradient(180deg,#8fd98f,#3ea23e);border-color:#2c7a2c}
.oct-bars li.hidden .t{background:repeating-linear-gradient(135deg,#e4e9f2,#e4e9f2 5px,#cfd8e6 5px,#cfd8e6 10px);border-style:dashed;border-color:#9aa8bd;width:14%}
.oct-bars .v{font-family:var(--font-mono);font-size:8.5pt;color:#4a5870;white-space:nowrap}
.oct-read{margin:0;padding:2px 12px 10px;font-size:8.5pt;color:#5b6879}
.oct-falsify{border-left:3px solid #c9a227;background:#fffbe8;padding:8px 10px;margin:14px 0 0}
@media(max-width:620px){.oct-bars li{grid-template-columns:8.5em 1fr;row-gap:2px}.oct-bars .v{grid-column:2}}

pageJs:
(function(){
  // Framework rows are the Nextane README's published benchmark (one small
  // hydrated getServerSideProps page, gzip). The two site rows are measured
  // from this repo's own build output at the same compression, 2026-07-31.
  var ROWS = [
    { n: "Next.js 16.2.12",  kib: 110.0 },
    { n: "Vinext 1.0.0-b4",  kib: 77.8 },
    { n: "Nextane + Octane", kib: 43.0 },
    { n: "aadhar.sh /lens",  kib: 36.6, mine: true, hide: true },
    { n: "aadhar.sh home",   kib: 14.9, mine: true, hide: true }
  ];
  var BEFORE = "Three frameworks, ranked. The two hidden rows are this site's heaviest page and its homepage. Where do they land?";
  var AFTER = "The homepage is 14.9 KiB against the winning framework's 43.0, so roughly a third. The heaviest page here still sits under that row. Read it as a scale rather than a verdict: 43.0 KiB is a real win against React and a large number against no framework.";

  var host = document.getElementById("oct-demo");
  if (!host) return;
  var list = host.querySelector(".oct-bars");
  var read = host.querySelector(".oct-read");
  var button = host.querySelector(".oct-reveal");
  var max = 0, i;
  for (i = 0; i < ROWS.length; i++) if (ROWS[i].kib > max) max = ROWS[i].kib;
  var revealed = false;

  function draw() {
    list.textContent = "";
    for (var j = 0; j < ROWS.length; j++) {
      var row = ROWS[j];
      var covered = row.hide && !revealed;
      var li = document.createElement("li");
      li.className = (row.mine ? "mine" : "") + (covered ? " hidden" : "");
      var n = document.createElement("span");
      n.className = "n";
      n.textContent = row.n;
      var t = document.createElement("span");
      t.className = "t";
      if (!covered) t.style.width = (row.kib / max) * 100 + "%";
      var v = document.createElement("span");
      v.className = "v";
      v.textContent = covered ? "?" : row.kib.toFixed(1) + " KiB";
      li.appendChild(n);
      li.appendChild(t);
      li.appendChild(v);
      list.appendChild(li);
    }
    read.textContent = revealed ? AFTER : BEFORE;
  }

  button.addEventListener("click", function(){
    revealed = true;
    button.disabled = true;
    button.textContent = "revealed";
    draw();
  });
  draw();
})();
